/**
 * End-to-end MemoryStore reproducers for the physical-operator review (Routine C). Every expected bag is hand-computed
 * from SPARQL 1.1 bottom-up semantics (sub-SELECT and MINUS operands are evaluated independently of the enclosing
 * group's bindings).
 */
class OperatorContractReviewReproTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String PREFIX = "PREFIX : <urn:ex:>\n";

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	private static IRI iri(String local) {
		return VF.createIRI("urn:ex:" + local);
	}

	// ---------------------------------------------------------------------------------------------------------
	// Candidate 3: OPTIONAL over a sub-SELECT / MINUS
	// ---------------------------------------------------------------------------------------------------------

	@ParameterizedTest(name = "condition={0}")
	@ValueSource(strings = { "", "FILTER(BOUND(?t))", "FILTER(?t != ?s)" })
	void optionalOverSubSelectDoesNotLeakOuterBindingIntoNonProjectedVariable(String condition) {
		add(iri("a"), iri("p"), VF.createLiteral(1));
		add(iri("c"), iri("r"), VF.createLiteral(2));
		String query = PREFIX + """
				SELECT ?s ?x ?t WHERE {
				  ?s :p ?x
				  OPTIONAL { { SELECT ?t WHERE { ?t :r ?x } } %s }
				}
				""".formatted(condition);
		assertThat(rows(query)).containsExactly("{s=urn:ex:a, t=urn:ex:c, x=1}");
	}

	@ParameterizedTest(name = "condition={0}")
	@ValueSource(strings = { "", "FILTER(BOUND(?t))", "FILTER(?t != ?s)" })
	void optionalOverLimitedSubSelectIsEvaluatedIndependently(String condition) {
		add(iri("a"), iri("p"), VF.createLiteral(2));
		add(iri("c"), iri("r"), VF.createLiteral(1));
		add(iri("d"), iri("r"), VF.createLiteral(2));
		// the sub-select alone yields exactly {t=:c, x=1}; it is incompatible with the left row x=2
		String query = PREFIX + """
				SELECT ?s ?x ?t WHERE {
				  ?s :p ?x
				  OPTIONAL { { SELECT ?t ?x WHERE { ?t :r ?x } ORDER BY ?x LIMIT 1 } %s }
				}
				""".formatted(condition);
		assertThat(rows(query)).containsExactly("{s=urn:ex:a, x=2}");
	}

	@ParameterizedTest(name = "condition={0}")
	@ValueSource(strings = { "", "FILTER(?n > 0)", "FILTER(?n > 0 && BOUND(?s))" })
	void optionalOverAggregateSubSelectIsEvaluatedIndependently(String condition) {
		add(iri("a"), iri("p"), iri("o1"));
		add(iri("t1"), iri("r"), iri("o1"));
		add(iri("t2"), iri("r"), iri("o2"));
		String query = PREFIX + """
				SELECT ?s ?n WHERE {
				  ?s :p ?o
				  OPTIONAL { { SELECT (COUNT(?o) AS ?n) WHERE { ?t :r ?o } } %s }
				}
				""".formatted(condition);
		assertThat(rows(query)).containsExactly("{n=2, s=urn:ex:a}");
	}

	@ParameterizedTest(name = "condition={0}")
	@ValueSource(strings = { "", "FILTER(BOUND(?y))", "FILTER(?y != ?s)" })
	void minusInsideOptionalIsEvaluatedIndependently(String condition) {
		add(iri("a"), iri("p"), iri("z1"));
		add(iri("a"), iri("q"), iri("b"));
		add(iri("b"), iri("r"), iri("z2"));
		// OPTIONAL operand: {s=a,y=b} MINUS {y=b,z=z2} is empty (shared y), so the left row stays unextended
		String query = PREFIX + """
				SELECT ?s ?z ?y WHERE {
				  ?s :p ?z
				  OPTIONAL { ?s :q ?y MINUS { ?y :r ?z } %s }
				}
				""".formatted(condition);
		assertThat(rows(query)).containsExactly("{s=urn:ex:a, z=urn:ex:z1}");
	}

	@ParameterizedTest(name = "maxMaterializedRightRows={0}")
	@ValueSource(strings = { "1", "1000000" })
	void adaptiveHashOptionalFallbackKeepsResults(String maxRows) {
		add(iri("a"), iri("p"), VF.createLiteral(1));
		add(iri("a"), iri("q"), VF.createLiteral(10));
		add(iri("a"), iri("r"), VF.createLiteral(11));
		add(iri("b"), iri("p"), VF.createLiteral(2));
		add(iri("c"), iri("q"), VF.createLiteral(12));
		String previous = System.getProperty(LeftJoinQueryEvaluationStep.MAX_MATERIALIZED_RIGHT_ROWS_PROPERTY);
		System.setProperty(LeftJoinQueryEvaluationStep.MAX_MATERIALIZED_RIGHT_ROWS_PROPERTY, maxRows);
		try {
			String query = PREFIX + """
					SELECT ?s ?x ?y WHERE {
					  ?s :p ?x
					  OPTIONAL { { ?s :q ?y } UNION { ?s :r ?y } }
					}
					""";
			assertThat(rows(query)).containsExactly(
					"{s=urn:ex:a, x=1, y=10}",
					"{s=urn:ex:a, x=1, y=11}",
					"{s=urn:ex:b, x=2}");
		} finally {
			if (previous == null) {
				System.clearProperty(LeftJoinQueryEvaluationStep.MAX_MATERIALIZED_RIGHT_ROWS_PROPERTY);
			} else {
				System.setProperty(LeftJoinQueryEvaluationStep.MAX_MATERIALIZED_RIGHT_ROWS_PROPERTY, previous);
			}
		}
	}

	// ---------------------------------------------------------------------------------------------------------
	// Candidate 6: EXISTS over a sub-SELECT (per-probe substitution descends into the sub-select scope)
	// ---------------------------------------------------------------------------------------------------------

	@ParameterizedTest(name = "negated={0}")
	@ValueSource(booleans = { false, true })
	void existsOverSubSelectDoesNotSubstituteNonProjectedVariable(boolean negated) {
		add(iri("a"), iri("p"), VF.createLiteral(1));
		add(iri("c"), iri("r"), VF.createLiteral(2));
		String query = PREFIX + """
				SELECT ?s WHERE {
				  ?s :p ?x
				  FILTER %s { { SELECT ?t WHERE { ?t :r ?x } } }
				}
				""".formatted(negated ? "NOT EXISTS" : "EXISTS");
		if (negated) {
			assertThat(rows(query)).isEmpty();
		} else {
			assertThat(rows(query)).containsExactly("{s=urn:ex:a}");
		}
	}

	@ParameterizedTest(name = "negated={0}")
	@ValueSource(booleans = { false, true })
	void existsOverAggregateSubSelectDoesNotSubstituteNonProjectedVariable(boolean negated) {
		add(iri("a"), iri("p"), iri("o1"));
		add(iri("t1"), iri("r"), iri("o1"));
		add(iri("t2"), iri("r"), iri("o2"));
		// COUNT over all :r triples is 2, so HAVING(?n > 1) holds independently of the outer ?o
		String query = PREFIX + """
				SELECT ?s WHERE {
				  ?s :p ?o
				  FILTER %s { SELECT (COUNT(?o) AS ?n) WHERE { ?t :r ?o } HAVING (COUNT(?o) > 1) }
				}
				""".formatted(negated ? "NOT EXISTS" : "EXISTS");
		if (negated) {
			assertThat(rows(query)).isEmpty();
		} else {
			assertThat(rows(query)).containsExactly("{s=urn:ex:a}");
		}
	}

	// ---------------------------------------------------------------------------------------------------------
	// Candidate 5: adaptive EXISTS materialization (default for unplanned EXISTS)
	// ---------------------------------------------------------------------------------------------------------

	@Test
	void existsInsideJoinedGroupDoesNotSeeOuterJoinBinding() {
		List<String> expected = new ArrayList<>();
		for (int i = 0; i < 40; i++) {
			add(iri("s" + i), iri("q"), iri("o" + i));
			add(iri("s" + i), iri("r"), iri("w" + i));
			expected.add("{a=urn:ex:a, s=urn:ex:s" + i + "}");
		}
		add(iri("a"), iri("p"), iri("zzz"));
		expected.sort(Comparator.naturalOrder());
		// inside the group ?z is not in scope, so EXISTS { ?s :r ?z } only needs some :r edge from ?s
		String query = PREFIX + """
				SELECT ?a ?s WHERE {
				  ?a :p ?z .
				  { ?s :q ?o FILTER EXISTS { ?s :r ?z } }
				}
				""";
		assertThat(rows(query)).containsExactlyElementsOf(expected);
	}

	@ParameterizedTest(name = "negated={0}")
	@ValueSource(booleans = { false, true })
	void existsUnionBodyAfterMaterializationBudget(boolean negated) {
		List<String> expected = new ArrayList<>();
		for (int i = 0; i < 80; i++) {
			add(iri("s" + i), iri("p"), iri("x" + i));
			if (i % 2 == 0) {
				add(iri("s" + i), iri("q"), iri("y" + i));
			}
			if (i % 3 == 0) {
				add(iri("x" + i), iri("r"), iri("w"));
			}
			boolean exists = i % 2 == 0 || i % 3 == 0;
			if (exists != negated) {
				expected.add("{s=urn:ex:s" + i + "}");
			}
		}
		expected.sort(Comparator.naturalOrder());
		String query = PREFIX + """
				SELECT ?s WHERE {
				  ?s :p ?x
				  FILTER %s { { ?s :q ?y } UNION { ?x :r ?w } }
				}
				""".formatted(negated ? "NOT EXISTS" : "EXISTS");
		assertThat(rows(query)).containsExactlyElementsOf(expected);
	}

	// ---------------------------------------------------------------------------------------------------------

	private void add(IRI subject, IRI predicate, Value object) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, object);
		}
	}

	private List<String> rows(String query) {
		List<String> rows = new ArrayList<>();
		try (SailRepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			while (result.hasNext()) {
				BindingSet bindingSet = result.next();
				TreeMap<String, String> sorted = new TreeMap<>();
				for (String name : bindingSet.getBindingNames()) {
					Value value = bindingSet.getValue(name);
					if (value != null) {
						sorted.put(name, value.stringValue());
					}
				}
				rows.add(sorted.toString());
			}
		}
		rows.sort(Comparator.naturalOrder());
		return rows;
	}
}
